      es: "El Cerro Tres Kandú es el punto más alto del Paraguay y ofrece una vista espectacular.",
      pt: "O Cerro Tres Kandú é o ponto mais alto do Paraguai e oferece uma vista espetacular.",
      fr: "Le Cerro Tres Kandú est le point culminant du Paraguay et offre une vue spectaculaire.",
